  const notice = (message: string, kind = ''): void => { $('notice').textContent = message; $('notice').className = 'notice' + (kind ? ' ' + kind : ''); translateAdmin(); };
  const empty = (message: string): string => '<div class="empty">' + x(message) + '</div>';
  const button = (action: string, id: string, label: string, allowed = true): string => allowed ? '<button type="button" class="btn small secondary" data-action="' + x(action) + '" data-id="' + x(id) + '">' + x(label) + '</button>' : '';
  const row = (title: unknown, meta: string, status = '', actions = ''): string => '<div class="row"><div class="row-title">' + x(title) + (status ? '<span class="badge' + (/draft|pending|needs|blocked|missing/.test(status) ? ' warn' : '') + '">' + x(status) + '</span>' : '') + '</div><div class="row-meta">' + meta + '</div>' + (actions ? '<div class="row-actions">' + actions + '</div>' : '') + '</div>';
  const renderList = (id: string, html: string, noData: string): void => { $(id).innerHTML = html || empty(noData); };
  const date = (input: unknown): string => input ? new Date(String(input)).toLocaleString() : '未确认';
  const money = (input: unknown): string => typeof input === 'number' ? (input / 100).toLocaleString() + ' BDT' : '缺失';
  async function api(path: string, method = 'GET', body?: unknown): Promise<any> {
    const response = await fetch(path, { method, credentials: 'same-origin', headers: method === 'GET' ? {} : { 'content-type': 'application/json', 'x-csrf-token': me?.csrf_token || '' }, body: method === 'GET' ? undefined : JSON.stringify(body || {}) });
    let data: any = {}; try { data = await response.json(); } catch {}
    if (!response.ok) { const messages: Record<string,string> = { event_date_required:'请先补齐活动开始与结束时间。', event_date_invalid:'活动结束时间必须晚于开始时间。', event_not_open:'活动尚未开放。', registration_not_found:'请先登记该会员报名。', event_capacity_full:'活动人数已满。', manual_reply_evidence_required:'请先记录人工回复的执行证据。' }; throw new Error(messages[data.error_code] || data.message || data.error_code || '请求失败：' + response.status); }
    return data;
  }
  function page(name: string): void {
    document.querySelectorAll<HTMLButtonElement>('.nav button').forEach(b => b.setAttribute('aria-current', b.dataset.page === name ? 'page' : 'false'));
    document.querySelectorAll<HTMLElement>('.page').forEach(section => { section.hidden = section.id !== 'page-' + name; });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function selectOptions(selector: string, options: Array<{ id: string; label: string }>): void {
    document.querySelectorAll<HTMLSelectElement>(selector).forEach(select => { const prev = select.value; select.innerHTML = '<option value="">请选择</option>' + options.map(o => '<option value="' + x(o.id) + '">' + x(o.label) + '</option>').join(''); if (options.some(o => o.id === prev)) select.value = prev; else if (options.length === 1) select.value = options[0].id; });
  }
  async function refresh(): Promise<void> {
    try { health = await api('/api/healthz'); $('mode').textContent = health.mode.toUpperCase() + (health.demo && health.mode !== 'demo' ? ' · DEMO' : ''); $('production-empty').hidden=!(health.mode==='production'&&!health.has_business_data); if ($('notice').textContent === '正在连接服务…') notice(health.mode === 'demo' ? '演示环境已就绪。外部渠道未配置时仅支持受控的人工流程。' : '环境已就绪，请按资料和审批状态继续。'); } catch { notice('服务未就绪，请检查本地进程。', 'error'); }
    try { me = await api('/api/me'); } catch { me = null; }
    $('login').hidden = Boolean(me); $('workspace').hidden = !me; $('logout').hidden = !me; $('user-label').textContent = me ? me.user.display_name + ' · ' + me.role : '';
    if (!me) { translateAdmin(); return; }
    const sources: Array<[string, string, string]> = [['brand','/api/brand/overview','brand:read'],['campaigns','/api/campaigns','campaign:read'],['offers','/api/offers','campaign:read'],['content','/api/content','campaign:read'],['imports','/api/imports','brand:read'],['metrics','/api/metrics','report:read'],['outreach','/api/outreach','outreach:read'],['events','/api/events','campaign:read'],['templates','/api/events/templates','campaign:read'],['partners','/api/partners','campaign:read'],['feedback','/api/feedback','report:read'],['cases','/api/support-cases','report:read'],['daily','/api/reports/daily','report:read']];
    await Promise.all(sources.map(async ([key, path, permission]) => { try { db[key] = can(permission) ? await api(path) : {}; } catch { db[key] = {}; } }));
    render();
  }
